contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a proposalID and use voteProposal to attempt to trigger finalising.
    // Precondition: proposalID must be between 1 and a reasonable bound to avoid zero id (fresh contract has 0 proposals).
    function run(uint proposalID) public payable {
        require(proposalID >= 1);

        // Read whether it was finalising before the call
        bool wasFinalising = c.mapPID_finalising(proposalID);
        // Read votes and totalWeight to determine whether quorum currently holds
        uint beforeVotes = c.mapPID_votes(proposalID);
        uint totalW = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).totalWeight();
        // Compute whether quorum condition (as implemented) would be satisfied before the call
        bool hadQuorumBefore = beforeVotes > totalW / 3;

        // Perform the call: voteProposal may update votes and potentially start finalising
        bool reverted;
        try c.voteProposal(proposalID) returns (uint v) { reverted = false; } catch { reverted = true; }

        // After-call observed finalising flag
        bool isFinalising = c.mapPID_finalising(proposalID);

        // General rule: If the call did not revert, and quorum already held before the call, and it wasn't already finalising,
        // then after the call the proposal must be in finalising state (mapPID_finalising == true).
        assert(!(reverted == false && hadQuorumBefore && wasFinalising == false) || isFinalising == true);
    }

    // Minimal interface to query VAULT.totalWeight without redeclaring contracts: use the public getter via address cast
    // Provide a fallback to accept Ether if needed by other tests
    receive() external payable {}
}

