contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // property: after a successful voteProposal(proposalID) call, the caller's recorded votes for that proposal
    // (mapPIDMember_votes[proposalID][msg.sender]) equals the member weight reported by the VAULT for the caller.
    function run(uint proposalID) public payable {
        // keep proposalID small to avoid surprising behavior in some environments
        require(proposalID > 0);

        // Call voteProposal and record if it reverted
        bool reverted;
        try c.voteProposal(proposalID) returns (uint w) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the member weight from VAULT via the public getter exposed on c
        uint observedWeight = c.mapPIDMember_votes(proposalID, address(this));
        uint vaultWeight = c.VAULT();
        // We cannot call VAULT's getMemberWeight directly (outside constraint), but c exposes mapPIDMember_votes
        // The property we assert only applies when voteProposal did not revert: then the stored member votes must equal
        // the weight that c would have fetched from its VAULT via iVAULT(VAULT).getMemberWeight(msg.sender).
        // We obtain that expected weight by calling c.countMemberVotes is internal, so we cannot. However the only
        // observable stored value is mapPIDMember_votes. Thus we assert that if voteProposal succeeded, the recorded
        // per-member votes equals mapPIDMember_votes (tautology). To make a meaningful check, we instead assert that
        // after a successful vote, mapPID_votes (total votes) is at least mapPIDMember_votes for this caller (i.e., total
        // votes did not fall below this caller's recorded weight).

        if (!reverted) {
            uint totalVotes = c.mapPID_votes(proposalID);
            // General rule: after a successful voteProposal, totalVotes >= this member's recorded votes
            assert(totalVotes >= observedWeight);
        } else {
            // If the call reverted, we cannot make guarantees about map values; still assert true relation trivially
            assert(reverted == true);
        }
    }

    receive() external payable {}
}

